#[derive(Debug, Clone, PartialEq, Eq)]
struct InlineComposerAttachment {
    attachment: ComposerAttachment,
    marker: String,
}

impl InlineComposerAttachment {
    fn range_in(&self, text: &str) -> Option<Range<usize>> {
        text.find(&self.marker)
            .map(|start| start..start + self.marker.len())
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct ComposerSessionDraft {
    text: String,
    attachments: Vec<InlineComposerAttachment>,
    command_entry: Option<AgentCommandEntry>,
}

impl ComposerSessionDraft {
    fn is_empty(&self) -> bool {
        self.text.is_empty() && self.attachments.is_empty() && self.command_entry.is_none()
    }
}

fn store_composer_session_draft(
    drafts: &mut BTreeMap<String, ComposerSessionDraft>,
    session_id: &VibexSessionId,
    draft: ComposerSessionDraft,
) {
    if draft.is_empty() {
        drafts.remove(session_id.as_str());
    } else {
        drafts.insert(session_id.as_str().to_string(), draft);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum InlineAttachmentEdit {
    Backspace,
    Delete,
    Left,
    Right,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ComposerSuggestionAction {
    Previous,
    Next,
    Apply,
    Dismiss,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ComposerTarget {
    Session,
    NewSession,
}

impl ComposerTarget {
    fn id(self) -> &'static str {
        match self {
            Self::Session => "session",
            Self::NewSession => "new-session",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ComposerSuggestionContext {
    target: ComposerTarget,
    request: AgentCommandDiscoverRequest,
    character_range: Range<usize>,
}

fn composer_suggestion_collection_matches(
    current: &ComposerSuggestionContext,
    next: &ComposerSuggestionContext,
) -> bool {
    current.target == next.target
        && current.request.agent_id == next.request.agent_id
        && current.request.provider_profile_id == next.request.provider_profile_id
        && current.request.session_id == next.request.session_id
        && current.request.workspace_id == next.request.workspace_id
        && current.request.trigger == next.request.trigger
}

fn composer_suggestion_description(entry: &AgentCommandEntry) -> Option<String> {
    if entry.source_kind == AgentCommandSourceKind::Reference {
        return entry.reference_path.clone();
    }
    entry
        .description
        .clone()
        .filter(|value| !value.trim().is_empty())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ComposerCommandInvocation {
    command_id: Option<String>,
    trigger: AgentCommandTrigger,
    source_kind: AgentCommandSourceKind,
    command_text: String,
    command_name: Option<String>,
    arguments: Option<String>,
    prompt_id: Option<PromptId>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ComposerQueueMessage {
    id: u64,
    session_id: VibexSessionId,
    desired_runtime: SessionRuntimeSelection,
    text: String,
    attachments: Vec<MessageAttachment>,
    command_invocation: Option<ComposerCommandInvocation>,
}

impl ComposerQueueMessage {
    fn display_text(&self) -> String {
        let text = self.text.split_whitespace().collect::<Vec<_>>().join(" ");
        if !text.is_empty() {
            text
        } else {
            format!("{} attachment(s)", self.attachments.len())
        }
    }
}

