fn toggled_sidebar_display(
    docked: bool,
    requested_open: bool,
    drawer_open: bool,
) -> SidebarDisplayState {
    if drawer_open {
        SidebarDisplayState {
            requested_open,
            drawer_open: false,
        }
    } else if docked {
        SidebarDisplayState {
            requested_open: !requested_open,
            drawer_open: false,
        }
    } else {
        SidebarDisplayState {
            requested_open: true,
            drawer_open: true,
        }
    }
}

