fn permission_request_display_title(request: &vibex_core::PermissionRequest) -> String {
    let normalized = normalize_permission_detail_label(&request.title);
    if matches!(
        normalized.as_str(),
        "execute" | "command" | "run" | "terminal" | "permission" | "allow"
    ) {
        return match request.risk_category {
            vibex_core::PermissionRiskCategory::Command => locale::text(
                "The Agent is requesting permission to run a command.",
                "Agent 请求运行一条命令。",
                "Agent 請求執行一條命令。",
            ),
            vibex_core::PermissionRiskCategory::FileReadSensitive => locale::text(
                "The Agent is requesting access to a sensitive file.",
                "Agent 请求访问敏感文件。",
                "Agent 請求存取敏感檔案。",
            ),
            vibex_core::PermissionRiskCategory::FileWrite => locale::text(
                "The Agent is requesting permission to change a file.",
                "Agent 请求修改文件。",
                "Agent 請求修改檔案。",
            ),
            vibex_core::PermissionRiskCategory::FileDeleteOrMove => locale::text(
                "The Agent is requesting permission to delete or move a file.",
                "Agent 请求删除或移动文件。",
                "Agent 請求刪除或移動檔案。",
            ),
            vibex_core::PermissionRiskCategory::Network => locale::text(
                "The Agent is requesting network access.",
                "Agent 请求访问网络。",
                "Agent 請求存取網路。",
            ),
            vibex_core::PermissionRiskCategory::GitDestructive => locale::text(
                "The Agent is requesting a destructive Git action.",
                "Agent 请求执行 Git 危险操作。",
                "Agent 請求執行 Git 危險操作。",
            ),
            vibex_core::PermissionRiskCategory::ProviderConfigExport => locale::text(
                "The Agent is requesting permission to export configuration.",
                "Agent 请求导出配置。",
                "Agent 請求匯出設定。",
            ),
            vibex_core::PermissionRiskCategory::CustomTool => locale::text(
                "The Agent is requesting permission to use a tool.",
                "Agent 请求执行工具操作。",
                "Agent 請求執行工具操作。",
            ),
        }
        .to_string();
    }
    request.title.clone()
}

fn permission_card_projection(request: &vibex_core::PermissionRequest) -> PermissionCardProjection {
    let mut projection = PermissionCardProjection {
        action: None,
        details: Vec::new(),
    };
    for detail in &request.details {
        let value = detail.value.trim();
        if value.is_empty() {
            continue;
        }
        let label = normalize_permission_detail_label(&detail.label);
        match label.as_str() {
            "command" | "cmd" | "shellcommand" => {
                projection.action.get_or_insert_with(|| value.to_string());
            }
            "input" | "rawinput" => {
                project_permission_input(value, &mut projection);
            }
            "cwd" | "workdir" | "workingdirectory" => {
                push_permission_detail(&mut projection.details, "cwd", value);
            }
            "args" | "arguments" => {
                push_permission_detail(&mut projection.details, "args", value);
            }
            label if label.contains("env") => {
                push_permission_detail(&mut projection.details, "env", value);
            }
            "tool" | "toolcallid" | "requestid" | "providerrequestid" | "source" => {}
            label if label.starts_with("option") => {}
            _ => push_permission_detail(&mut projection.details, &detail.label, value),
        }
    }
    projection
}

fn project_permission_input(value: &str, projection: &mut PermissionCardProjection) {
    let Ok(input) = serde_json::from_str::<serde_json::Value>(value) else {
        projection.action.get_or_insert_with(|| value.to_string());
        return;
    };
    let Some(object) = input.as_object() else {
        if let Some(value) = input.as_str() {
            projection.action.get_or_insert_with(|| value.to_string());
        }
        return;
    };
    if let Some(command) = ["command", "cmd", "shellCommand"]
        .iter()
        .find_map(|key| object.get(*key).and_then(serde_json::Value::as_str))
    {
        projection.action.get_or_insert_with(|| command.to_string());
    }
    if let Some(cwd) = ["cwd", "workdir", "workingDirectory"]
        .iter()
        .find_map(|key| object.get(*key).and_then(serde_json::Value::as_str))
    {
        push_permission_detail(&mut projection.details, "cwd", cwd);
    }
    if let Some(args) = object.get("args").and_then(serde_json::Value::as_array) {
        let args = args
            .iter()
            .filter_map(serde_json::Value::as_str)
            .collect::<Vec<_>>()
            .join(" ");
        if !args.is_empty() {
            push_permission_detail(&mut projection.details, "args", &args);
        }
    }
}

fn push_permission_detail(details: &mut Vec<(String, String)>, label: &str, value: &str) {
    if !details
        .iter()
        .any(|(existing_label, existing_value)| existing_label == label && existing_value == value)
    {
        details.push((label.to_string(), value.to_string()));
    }
}

fn normalize_permission_detail_label(label: &str) -> String {
    label
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn permission_detail_label(label: &str) -> String {
    match normalize_permission_detail_label(label).as_str() {
        "cwd" | "workdir" | "workingdirectory" => {
            locale::text("Working directory", "工作目录", "工作目錄").to_string()
        }
        "args" | "arguments" => locale::text("Arguments", "参数", "參數").to_string(),
        label if label.contains("env") => {
            locale::text("Environment", "环境变量", "環境變數").to_string()
        }
        _ => label.to_string(),
    }
}

fn permission_response_label(kind: PermissionResponseKind) -> &'static str {
    // Known-bug ledger `react.permission.raw-response-labels`: GPUI localizes the
    // response labels that Tauri rendered as raw enum values.
    match kind {
        PermissionResponseKind::Approve => locale::text("Approve", "允许", "允許"),
        PermissionResponseKind::Deny => locale::text("Deny", "拒绝", "拒絕"),
        PermissionResponseKind::AlwaysAllowForSession => locale::text(
            "Always allow for session",
            "本会话始终允许",
            "本會話始終允許",
        ),
    }
}

fn agent_progress_label(label: &str, fallback: &str) -> String {
    let (plain_text, _) = agent_markdown_summary(label);
    let compact = compact_agent_turn_preview_message(&plain_text);
    let stem = compact.trim_end().trim_end_matches(['.', '…']).trim_end();
    let has_visible_content = stem.chars().any(|character| {
        character.is_alphanumeric()
            || (!character.is_whitespace() && !character.is_ascii_punctuation())
    });
    let stem = if has_visible_content {
        stem
    } else {
        fallback.trim_end().trim_end_matches(['.', '…']).trim_end()
    };
    format!("{stem}...")
}

fn agent_progress_tooltip(label: &str, fallback: &str) -> String {
    let (plain_text, _) = agent_markdown_summary(label);
    let text = plain_text.trim();
    if text.is_empty() {
        fallback.to_string()
    } else {
        text.to_string()
    }
}

fn agent_thinking_scroll_progress(delta: f32) -> f32 {
    const START_HOLD: f32 = 0.18;
    const END_HOLD: f32 = 0.18;

    if delta <= START_HOLD {
        0.0
    } else if delta >= 1.0 - END_HOLD {
        1.0
    } else {
        (delta - START_HOLD) / (1.0 - START_HOLD - END_HOLD)
    }
}

fn shimmer_scan_position(delta: f32, visible_start: f32, visible_span: f32) -> f32 {
    visible_start - visible_span * 0.35 + (delta * SHIMMER_SCAN_PASSES).fract() * visible_span * 1.7
}

fn shimmer_color(
    base: Hsla,
    glow: Hsla,
    position: f32,
    scan_position: f32,
    scan_radius: f32,
) -> Hsla {
    let intensity = (1.0 - (position - scan_position).abs() / scan_radius).clamp(0.0, 1.0);
    let intensity = intensity * intensity * (3.0 - 2.0 * intensity);
    Hsla {
        h: base.h + (glow.h - base.h) * intensity,
        s: base.s + (glow.s - base.s) * intensity,
        l: base.l + (glow.l - base.l) * intensity,
        a: base.a + (glow.a - base.a) * intensity,
    }
}

fn render_agent_thinking_indicator(
    turn_id: &str,
    label: &str,
    tooltip: &str,
    cx: &App,
) -> AnyElement {
    let base = cx.theme().muted_foreground.opacity(0.75);
    let glow = cx.theme().foreground;
    let background = cx.theme().background;
    let label = label.to_string();
    let character_count = label.chars().count();
    let tooltip = tooltip.to_string();
    let element_id = format!("agent-thinking-{turn_id}");
    let animation_id = format!("{element_id}-animation");
    let scroll_id = format!("{element_id}-scroll");
    let scroll = gpui::ScrollHandle::new();
    let animation_scroll = scroll.clone();
    h_flex()
        .w_full()
        .min_w_0()
        .justify_start()
        .py_1()
        .child(
            div()
                .id(element_id)
                .relative()
                .min_w_0()
                .flex_1()
                .overflow_hidden()
                .text_sm()
                .tooltip(move |window, cx| Tooltip::new(tooltip.clone()).build(window, cx))
                .with_animation(
                    animation_id,
                    Animation::new(AGENT_THINKING_SCROLL_DURATION).repeat(),
                    move |this, delta| {
                        let progress = agent_thinking_scroll_progress(delta);
                        let max_offset = animation_scroll.max_offset().x;
                        animation_scroll.set_offset(point(-max_offset * progress, px(0.0)));
                        let viewport_width = f32::from(animation_scroll.bounds().size.width);
                        let content_width = viewport_width + f32::from(max_offset);
                        let visible_span = if content_width > 0.0 {
                            (viewport_width / content_width).clamp(0.0, 1.0)
                        } else {
                            1.0
                        };
                        let visible_start = progress * (1.0 - visible_span);
                        let scan_position =
                            shimmer_scan_position(delta, visible_start, visible_span);
                        let scan_radius = (visible_span * 0.42).max(0.01);
                        this.child(
                            div()
                                .id(scroll_id.clone())
                                .w_full()
                                .overflow_x_scroll()
                                .track_scroll(&animation_scroll)
                                .child(h_flex().flex_none().whitespace_nowrap().children(
                                    label.chars().enumerate().map(|(index, character)| {
                                        let position = if character_count > 1 {
                                            index as f32 / (character_count - 1) as f32
                                        } else {
                                            0.5
                                        };
                                        div().flex_none().child(character.to_string()).text_color(
                                            shimmer_color(
                                                base,
                                                glow,
                                                position,
                                                scan_position,
                                                scan_radius,
                                            ),
                                        )
                                    }),
                                )),
                        )
                        .when(
                            max_offset > px(0.0) && progress < 1.0,
                            |this| {
                                this.child(
                                    div()
                                        .absolute()
                                        .top_0()
                                        .right_0()
                                        .bottom_0()
                                        .pl_1()
                                        .bg(background)
                                        .text_color(base)
                                        .child("…"),
                                )
                            },
                        )
                    },
                ),
        )
        .into_any_element()
}

fn tool_card_projection(
    row: &TimelineRow,
    payload: Option<&vibex_core::TimelinePayload>,
) -> ToolCardProjection {
    use vibex_core::TimelinePayload as Payload;
    use vibex_core::ToolCallStatus as Status;
    match payload {
        Some(Payload::ToolCall(tool)) => {
            let title = if tool.summary.is_empty() {
                tool.tool_name.clone()
            } else {
                tool.summary.clone()
            };
            let mut details = vec![("tool".to_string(), tool.tool_name.clone())];
            if let Some(input) = tool.input_summary.as_ref().filter(|s| !s.is_empty()) {
                details.push(("input".to_string(), input.clone()));
            }
            if let Some(output) = tool.output_summary.as_ref().filter(|s| !s.is_empty()) {
                details.push(("output".to_string(), output.clone()));
            }
            ToolCardProjection {
                title,
                details,
                failed: tool.status == Status::Failed,
                icon: generic_tool_activity_icon(&tool.tool_name, &tool.summary),
            }
        }
        Some(Payload::FileOperation(operation)) => ToolCardProjection {
            title: format!(
                "{} {}",
                file_operation_verb(operation.operation),
                operation.path
            ),
            details: vec![
                ("file".to_string(), operation.path.clone()),
                ("summary".to_string(), operation.summary.clone()),
            ],
            failed: false,
            icon: match operation.operation {
                vibex_core::FileOperationKind::Read => ProcessActivityIcon::FileRead,
                vibex_core::FileOperationKind::Write => ProcessActivityIcon::FileCreate,
                vibex_core::FileOperationKind::Edit | vibex_core::FileOperationKind::Move => {
                    ProcessActivityIcon::FileEdit
                }
                vibex_core::FileOperationKind::Delete => ProcessActivityIcon::FileDelete,
            },
        },
        Some(Payload::WebSearch(search)) => {
            let mut details = vec![("query".to_string(), search.query.clone())];
            if let Some(result) = search.result_summary.as_ref().filter(|s| !s.is_empty()) {
                details.push(("result".to_string(), result.clone()));
            }
            ToolCardProjection {
                title: search.query.clone(),
                details,
                failed: search.status == Status::Failed,
                icon: ProcessActivityIcon::Search,
            }
        }
        Some(Payload::TodoUpdate(todo)) => ToolCardProjection {
            title: todo.title.clone(),
            details: todo
                .items
                .iter()
                .map(|item| {
                    (
                        plan_step_status_text(item.status).to_string(),
                        item.title.clone(),
                    )
                })
                .collect(),
            failed: false,
            icon: ProcessActivityIcon::Todo,
        },
        Some(Payload::Collaboration(collaboration)) => {
            let mut details = vec![("action".to_string(), collaboration.action.clone())];
            if let Some(agent) = collaboration.agent_label.as_ref().filter(|s| !s.is_empty()) {
                details.push(("agent".to_string(), agent.clone()));
            }
            details.push(("summary".to_string(), collaboration.summary.clone()));
            ToolCardProjection {
                title: if collaboration.summary.is_empty() {
                    collaboration.action.clone()
                } else {
                    collaboration.summary.clone()
                },
                details,
                failed: collaboration.status == Status::Failed,
                icon: ProcessActivityIcon::Collaboration,
            }
        }
        Some(Payload::Command(command)) => {
            let mut details = Vec::new();
            if let Some(cwd) = command.cwd.as_ref().filter(|s| !s.is_empty()) {
                details.push(("cwd".to_string(), cwd.clone()));
            }
            details.push(("command".to_string(), command.command.clone()));
            if let Some(output) = command.output_summary.as_ref().filter(|s| !s.is_empty()) {
                details.push(("output".to_string(), output.clone()));
            }
            if let Some(exit_code) = command.exit_code {
                details.push(("exit".to_string(), exit_code.to_string()));
            }
            ToolCardProjection {
                title: command.command.clone(),
                details,
                failed: command.status == vibex_core::CommandStatus::Failed,
                icon: ProcessActivityIcon::Command,
            }
        }
        Some(Payload::ImageGeneration(image)) => {
            let mut details = Vec::new();
            if let Some(mime) = image.mime_type.as_ref().filter(|s| !s.is_empty()) {
                details.push(("type".to_string(), mime.clone()));
            }
            if let Some(reference) = image.image_reference.as_ref().filter(|s| !s.is_empty()) {
                details.push(("reference".to_string(), reference.clone()));
            }
            details.push(("summary".to_string(), image.summary.clone()));
            ToolCardProjection {
                title: "Image generation".to_string(),
                details,
                failed: image.status == Status::Failed,
                icon: ProcessActivityIcon::Image,
            }
        }
        _ => ToolCardProjection {
            title: row.title.clone(),
            details: if row.body.is_empty() {
                Vec::new()
            } else {
                vec![("summary".to_string(), row.body.clone())]
            },
            failed: row.failed,
            icon: match row.kind {
                TimelineRowKind::Command => ProcessActivityIcon::Command,
                TimelineRowKind::WebSearch => ProcessActivityIcon::Search,
                TimelineRowKind::FileOperation => ProcessActivityIcon::FileRead,
                TimelineRowKind::TodoUpdate => ProcessActivityIcon::Todo,
                TimelineRowKind::Collaboration => ProcessActivityIcon::Collaboration,
                TimelineRowKind::ImageGeneration => ProcessActivityIcon::Image,
                _ => ProcessActivityIcon::Generic,
            },
        },
    }
}
fn estimated_wrapped_lines(text: &str, chars_per_line: usize) -> usize {
    text.lines()
        .map(|line| line.chars().count().max(1).div_ceil(chars_per_line))
        .sum::<usize>()
        .max(1)
}

fn estimated_markdown_body_height(text: &str, chars_per_line: usize) -> f32 {
    estimated_wrapped_lines(text, chars_per_line) as f32 * 24.0
}

fn estimated_pre_block_height(value: &str) -> f32 {
    // Mirrors the mono detail block: 20px lines, 16px padding, 160px max height.
    // Mono 13px fits ~90 chars at the narrowest content width.
    ((estimated_wrapped_lines(value, 90) as f32) * 20.0 + 16.0).min(160.0)
}

fn estimated_detail_block_height(value: &str) -> f32 {
    // Uppercase label line plus the bounded mono block.
    24.0 + estimated_pre_block_height(value)
}

fn terminal_cwd_for_workspace_target(path: &str, kind: FileEntryKind) -> Option<String> {
    if std::path::Path::new(path).is_absolute() {
        return None;
    }
    let normalized = path.replace('\\', "/");
    let normalized = normalized.trim_matches('/');
    if normalized.is_empty() {
        return None;
    }
    if kind == FileEntryKind::Directory {
        return Some(normalized.to_string());
    }
    normalized
        .rsplit_once('/')
        .map(|(parent, _)| parent.to_string())
        .filter(|parent| !parent.is_empty())
}

fn this_terminal_shell(shell: &Option<String>) -> Option<String> {
    shell
        .as_ref()
        .map(|shell| shell.trim().to_string())
        .filter(|shell| !shell.is_empty())
}

fn terminal_preference_cwd(
    worktree_root: &str,
    project_root: Option<&str>,
    current_file: Option<&str>,
    preference: &TerminalWorkingDirectory,
) -> Option<String> {
    match preference {
        TerminalWorkingDirectory::CurrentWorktree => Some(worktree_root.to_string()),
        TerminalWorkingDirectory::ProjectRoot => project_root
            .filter(|project_root| {
                std::path::Path::new(project_root).starts_with(std::path::Path::new(worktree_root))
            })
            .map(str::to_string)
            .or_else(|| Some(worktree_root.to_string())),
        TerminalWorkingDirectory::CurrentFile => current_file
            .and_then(|path| terminal_cwd_for_workspace_target(path, FileEntryKind::File))
            .or_else(|| Some(worktree_root.to_string())),
    }
}

fn terminal_preference_target(
    worktree_root: &str,
    project_root: Option<&str>,
    current_file: Option<&str>,
    preference: &TerminalWorkingDirectory,
) -> (String, Option<String>) {
    let cwd = terminal_preference_cwd(worktree_root, project_root, current_file, preference);
    (worktree_root.to_string(), cwd)
}

fn workbench_route(
    ui_state: &DesktopUiStateV1,
    selected_session_id: Option<&VibexSessionId>,
) -> WorkbenchRoute {
    WorkbenchRoute {
        workspace_id: ui_state.workbench.selected_workspace_id.clone(),
        session_id: selected_session_id.map(|session_id| session_id.as_str().to_string()),
        usage_session_id: None,
        primary_tab: ui_state.workbench.active_tab.clone(),
        right_rail: if ui_state.workbench.right_rail_visible {
            ui_state
                .right_rail
                .selected_activity_id
                .clone()
                .unwrap_or_else(|| right_rail_activity_id(RightRailMode::Files).to_string())
        } else {
            String::new()
        },
        selected_file_path: ui_state.workbench.selected_file_path.clone(),
        selected_git_path: ui_state.workbench.selected_git_path.clone(),
        selected_terminal_id: ui_state.terminal.selected_terminal_id.clone(),
    }
}

fn complete_string_order(order: &mut Vec<String>, ids: Vec<String>) {
    let valid = ids.iter().cloned().collect::<BTreeSet<_>>();
    let mut seen = BTreeSet::new();
    order.retain(|id| valid.contains(id) && seen.insert(id.clone()));
    order.extend(ids.into_iter().filter(|id| seen.insert(id.clone())));
}

fn move_string_relative(
    order: &mut Vec<String>,
    moving_id: &str,
    target_id: &str,
    after: bool,
) -> bool {
    if moving_id == target_id {
        return false;
    }
    let Some(moving_index) = order.iter().position(|id| id == moving_id) else {
        return false;
    };
    let moving = order.remove(moving_index);
    let Some(target_index) = order.iter().position(|id| id == target_id) else {
        order.insert(moving_index.min(order.len()), moving);
        return false;
    };
    let insertion_index = target_index + usize::from(after);
    if insertion_index == moving_index {
        order.insert(moving_index, moving);
        return false;
    }
    order.insert(insertion_index, moving);
    true
}

fn reordered_string_ids(
    ordered_ids: &[String],
    moving_id: &str,
    target_id: &str,
    after: bool,
) -> Vec<String> {
    let mut reordered = ordered_ids.to_vec();
    let _ = move_string_relative(&mut reordered, moving_id, target_id, after);
    reordered
}

fn reorder_target_from_preview(
    original_ids: &[String],
    preview_ids: &[String],
    moving_id: &str,
) -> Option<(String, bool)> {
    let original_index = original_ids.iter().position(|id| id == moving_id)?;
    let preview_index = preview_ids.iter().position(|id| id == moving_id)?;
    if preview_index == original_index {
        return None;
    }
    if preview_index < original_index {
        preview_ids
            .get(preview_index + 1)
            .cloned()
            .map(|target_id| (target_id, false))
    } else {
        preview_index
            .checked_sub(1)
            .and_then(|index| preview_ids.get(index))
            .cloned()
            .map(|target_id| (target_id, true))
    }
}

fn reorder_target_from_cursor_offset(
    ordered_ids: &[String],
    moving_id: &str,
    cursor_offset_y: f32,
    row_height: f32,
    row_gap: f32,
) -> Option<(String, bool)> {
    let moving_index = ordered_ids.iter().position(|id| id == moving_id)?;
    let stride = row_height + row_gap;
    if stride <= 0.0 {
        return None;
    }
    let row_delta = ((cursor_offset_y - row_height / 2.0) / stride).round() as isize;
    if row_delta == 0 {
        return None;
    }
    let target_index = moving_index
        .saturating_add_signed(row_delta)
        .min(ordered_ids.len().saturating_sub(1));
    (target_index != moving_index).then(|| {
        (
            ordered_ids[target_index].clone(),
            target_index > moving_index,
        )
    })
}

fn sidebar_reorder_row_offset(
    original_ids: &[String],
    preview_ids: &[String],
    row_id: &str,
) -> Option<isize> {
    let original_index = original_ids.iter().position(|id| id == row_id)?;
    let preview_index = preview_ids.iter().position(|id| id == row_id)?;
    let offset = isize::try_from(original_index).ok()? - isize::try_from(preview_index).ok()?;
    (offset != 0).then_some(offset)
}

fn sidebar_sessions_with_drag_preview(
    sessions: &[AgentSession],
    drag: Option<&SidebarSessionDragState>,
) -> Vec<AgentSession> {
    let Some(drag) = drag else {
        return sessions.to_vec();
    };
    if !drag.flat_preview_enabled {
        return sessions.to_vec();
    }
    let mut reordered = sessions.to_vec();
    let slots = sessions
        .iter()
        .enumerate()
        .filter(|(_, session)| {
            session.workspace_id.as_str() == drag.workspace_id
                && drag.original_ids.iter().any(|id| id == session.id.as_str())
        })
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    if slots.len() != drag.preview_ids.len() {
        return reordered;
    }
    for (slot, session_id) in slots.into_iter().zip(&drag.preview_ids) {
        let Some(session) = sessions
            .iter()
            .find(|session| session.id.as_str() == session_id)
        else {
            return sessions.to_vec();
        };
        reordered[slot] = session.clone();
    }
    reordered
}

fn sidebar_organization_items_with_drag_preview(
    items: &[SidebarOrganizationItem],
    preview_items: &[SidebarOrganizationItem],
) -> Vec<SidebarOrganizationItem> {
    if items
        .iter()
        .any(|item| matches!(item, SidebarOrganizationItem::Folder(_)))
    {
        return items.to_vec();
    }
    let preview_set = preview_items.iter().cloned().collect::<BTreeSet<_>>();
    let slots = items
        .iter()
        .enumerate()
        .filter(|(_, item)| preview_set.contains(*item))
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    if slots.len() != preview_items.len() {
        return items.to_vec();
    }
    let mut reordered = items.to_vec();
    for (slot, item) in slots.into_iter().zip(preview_items) {
        reordered[slot] = item.clone();
    }
    reordered
}

fn sidebar_selection_state(
    session_ids: &[String],
    selected_ids: &BTreeSet<String>,
) -> SidebarSelectionState {
    let selected_count = session_ids
        .iter()
        .filter(|id| selected_ids.contains(*id))
        .count();
    if selected_count == 0 {
        SidebarSelectionState::Unchecked
    } else if selected_count == session_ids.len() {
        SidebarSelectionState::Checked
    } else {
        SidebarSelectionState::Indeterminate
    }
}

fn sidebar_project_is_active(
    selected_workspace_id: Option<&str>,
    workspace_id: &str,
    session_selected: bool,
) -> bool {
    !session_selected && selected_workspace_id == Some(workspace_id)
}

