    #[test]
    fn process_collapses_by_default_when_conclusion_streaming_starts() {
        let mut turn = TimelineConversationTurn {
            id: "turn:streaming-conclusion".into(),
            user_row: None,
            process_rows: Vec::new(),
            process_activity_groups: Vec::new(),
            process_activity_groups_with_commands: Vec::new(),
            process_activity_groups_with_file_operations: Vec::new(),
            process_activity_groups_with_commands_and_file_operations: Vec::new(),
            live_status: None,
            conclusion_row: Some(TimelineRow {
                id: "agent:streaming-conclusion".into(),
                kind: TimelineRowKind::AgentMessage,
                item_ids: vec!["timeline_1".into()],
                turn_id: Some("turn:streaming-conclusion".into()),
                turn_item_count: 1,
                turn_failed: false,
                turn_pending_permission: false,
                conclusion: true,
                first_sequence: 1,
                last_sequence: 1,
                title: "Agent".into(),
                body: "Streaming".into(),
                streaming: true,
                collapsible: false,
                pending_permission: false,
                failed: false,
                runtime_attribution: None,
                file_path: None,
            }),
            runtime_attribution: None,
            complete: false,
            failed: false,
            pending_permission: false,
            item_count: 1,
            started_at_ms: 1,
            ended_at_ms: Some(1),
        };

        assert!(!timeline_turn_process_expanded(&turn, None));
        assert!(timeline_turn_process_expanded(&turn, Some(true)));
        assert!(!show_agent_answer_actions(
            true,
            turn.conclusion_row.as_ref().unwrap()
        ));

        turn.conclusion_row.as_mut().unwrap().body = "   ".into();
        assert!(timeline_turn_conclusion_row(&turn).is_none());
        assert!(timeline_turn_process_expanded(&turn, None));
    }

