    #[tokio::test]
    async fn new_session_is_announced_before_initial_message_finishes() {
        let (created_tx, mut created_rx) = mpsc::unbounded_channel();
        let (release_tx, release_rx) = tokio::sync::oneshot::channel();
        let submission = tokio::spawn(announce_created_session_before_initial_message(
            created_tx,
            "session-created",
            Some(async move {
                release_rx.await.expect("submission release signal");
                Ok::<_, vibex_core::VibexError>(())
            }),
        ));

        assert_eq!(created_rx.recv().await, Some("session-created"));
        assert!(!submission.is_finished());

        release_tx.send(()).expect("release initial message");
        assert!(submission.await.expect("submission task").is_none());
    }

    #[test]
    fn initial_message_interrupt_is_not_reported_as_a_failure() {
        let interrupted = vibex_core::VibexError::conflict(
            "message_submission_interrupted_before_dispatch",
            "message submission was cancelled before dispatch",
        );
        assert_eq!(initial_message_failure_note(&interrupted), None);

        let failed = vibex_core::VibexError::provider("provider_failed", "provider failed");
        assert_eq!(
            initial_message_failure_note(&failed).as_deref(),
            Some("Session created; initial message failed: provider_failed: provider failed")
        );
    }

    #[test]
    fn fork_session_navigates_after_persistence_before_runtime_completion() {
        let source = include_str!("app.rs");
        let fork = source
            .split_once("    fn fork_session_at(")
            .and_then(|(_, tail)| tail.split_once("\n    fn begin_inline_user_message_edit("))
            .map(|(body, _)| body)
            .expect("fork session action should remain inspectable");

        let created = fork
            .find("created_rx.recv().await")
            .expect("fork should receive the durable session snapshot");
        let completed = fork
            .find("runner.await")
            .expect("fork should still observe final runtime initialization");

        assert!(fork.contains(".fork_session_with_created_callback("));
        assert!(created < completed);
        assert!(fork.contains("this.select_session_with_history(session_id, false, cx)"));
        assert!(fork.contains("Fork created. Preparing its runtime..."));
        assert!(fork.contains("Forked session is ready"));
    }

    #[test]
    fn persisted_composer_terminal_ids_partition_workspace_terminals() {
        let workspace_id = WorkspaceId::parse("workspace_test").unwrap();
        let terminals = vec![
            terminal_session("terminal_composer", &workspace_id),
            terminal_session("terminal_preview", &workspace_id),
        ];
        let (composer, workbench) =
            partition_terminal_sessions(terminals, &["terminal_composer".to_string()]);

        assert_eq!(
            composer
                .iter()
                .map(|terminal| terminal.id.as_str())
                .collect::<Vec<_>>(),
            ["terminal_composer"]
        );
        assert_eq!(
            workbench
                .iter()
                .map(|terminal| terminal.id.as_str())
                .collect::<Vec<_>>(),
            ["terminal_preview"]
        );
    }

