    #[test]
    fn startup_loading_indicator_is_delayed_for_five_seconds() {
        assert_eq!(STARTUP_LOADING_INDICATOR_DELAY, Duration::from_secs(5));
        assert_eq!(STARTUP_LOADING_MIN_DURATION, Duration::from_secs(1));
        let source = include_str!("app.rs");
        let scheduler = source
            .split_once("    fn schedule_startup_loading_indicator(")
            .and_then(|(_, tail)| tail.split_once("\n    fn apply_loaded_ui_state("))
            .map(|(body, _)| body)
            .expect("startup loading-indicator scheduler should remain inspectable");
        assert!(scheduler.contains(".timer(STARTUP_LOADING_INDICATOR_DELAY)"));
        assert!(scheduler.contains("if this.startup_loading"));
        assert!(scheduler.contains("this.startup_loading_indicator_visible = true"));

        let overlay = source
            .split_once("fn startup_loading_overlay(")
            .and_then(|(_, tail)| tail.split_once("\nimpl Render for VibexWorkbench"))
            .map(|(body, _)| body)
            .expect("startup overlay should remain inspectable");
        assert!(overlay.contains("startup_loading_wordmark(show_loading_indicator, cx)"));

        let wordmark = source
            .split_once("fn startup_loading_wordmark(")
            .and_then(|(_, tail)| tail.split_once("\nfn startup_loading_overlay("))
            .map(|(body, _)| body)
            .expect("startup loading wordmark should remain inspectable");
        assert!(wordmark.contains("icons/vibex/vibex-mark.svg"));
        assert!(wordmark.contains(".children(\"ibex\".chars().enumerate()"));
        assert!(wordmark.contains("scan_position.map_or(glow"));
        assert!(wordmark.contains(".with_animation("));
        assert!(wordmark.contains("shimmer_scan_position(delta, 0.0, 1.0)"));
        assert!(!wordmark.contains("Spinner::new()"));
    }

