    #[test]
    fn runtime_selection_validation_rejects_stale_feature_ids_and_values() {
        let mut option = new_session_runtime_option("codex", "Codex");
        option.features = vec![SessionRuntimeFeature {
            id: "approval_mode".into(),
            label: "Approval mode".into(),
            description: None,
            kind: SessionRuntimeFeatureKind::Select,
            current_value: Some(SessionConfigValue {
                value: "ask".into(),
                label: Some("Ask".into()),
            }),
            default_value: None,
            values: vec![
                SessionConfigValue {
                    value: "ask".into(),
                    label: Some("Ask".into()),
                },
                SessionConfigValue {
                    value: "auto".into(),
                    label: Some("Automatic".into()),
                },
            ],
        }];
        option
            .selection
            .config_values
            .insert("approval_mode".into(), "ask".into());
        let catalog = SessionRuntimeOptionCatalog {
            revision: 4,
            agents: Vec::new(),
            auth_sources: Vec::new(),
            options: vec![option],
        };
        let mut selection = catalog.options[0].selection.clone();
        assert!(catalog_has_runtime_selection(&catalog, &selection));

        selection
            .config_values
            .insert("approval_mode".into(), "invalid".into());
        assert!(!catalog_has_runtime_selection(&catalog, &selection));
        selection.config_values.clear();
        selection
            .config_values
            .insert("removed_feature".into(), "true".into());
        assert!(!catalog_has_runtime_selection(&catalog, &selection));
    }

