    #[test]
    fn inline_composer_attachments_follow_text_order_and_strip_markers() {
        let first = inline_composer_attachment(1, "first");
        let second = inline_composer_attachment(2, "second");
        let raw_text = format!("alpha{}beta{}omega", first.marker, second.marker);

        let (text, attachments) =
            composer_submission_payload(&raw_text, &[second.clone(), first.clone()]);

        assert_eq!(text, "alpha beta omega");
        assert_eq!(
            attachments
                .iter()
                .map(|attachment| attachment.label.as_str())
                .collect::<Vec<_>>(),
            ["first", "second"]
        );
        assert_eq!(attachments[0].inline_text_offset, Some(5));
        assert_eq!(attachments[1].inline_text_offset, Some(10));
        assert!(!text.contains(COMPOSER_INLINE_ATTACHMENT_PREFIX));
    }

    #[test]
    fn inline_composer_attachment_without_marker_is_not_submitted() {
        let attachment = inline_composer_attachment(1, "removed");

        let (text, attachments) = composer_submission_payload("plain text", &[attachment]);

        assert_eq!(text, "plain text");
        assert!(attachments.is_empty());
    }

