    #[test]
    fn user_message_edit_is_inline_and_scoped_to_its_session_row() {
        let source_session_id = VibexSessionId::parse("session_inline_edit").unwrap();
        let other_session_id = VibexSessionId::parse("session_inline_edit_other").unwrap();
        let edit = InlineUserMessageEdit {
            turn_id: "turn-7".into(),
            row_id: "timeline-row-7".into(),
            source_session_id: source_session_id.clone(),
            user_sequence: 7,
            expected_source_end_sequence: 9,
            attachments: Vec::new(),
        };
        assert!(edit.matches("timeline-row-7", Some(&source_session_id)));
        assert!(!edit.matches("timeline-row-8", Some(&source_session_id)));
        assert!(!edit.matches("timeline-row-7", Some(&other_session_id)));

        let source = include_str!("app.rs");
        let input_setup = source
            .split_once("        let user_message_edit_input =")
            .and_then(|(_, tail)| tail.split_once("\n        let composer_input ="))
            .map(|(body, _)| body)
            .expect("inline message edit input setup should remain inspectable");
        assert!(input_setup.contains(".submit_on_enter(true)"));
        let subscriptions = source
            .split_once("        let mut agent_subscriptions =")
            .and_then(|(_, tail)| tail.split_once("\n        let parent ="))
            .map(|(body, _)| body)
            .expect("input subscriptions should remain inspectable");
        assert!(subscriptions.contains("InputEvent::PressEnter { shift: false, .. }"));
        assert!(subscriptions.contains("submit_inline_user_message_edit(window, cx)"));
        let begin = source
            .split_once("    fn begin_inline_user_message_edit(")
            .and_then(|(_, tail)| tail.split_once("\n    fn cancel_inline_user_message_edit("))
            .map(|(body, _)| body)
            .expect("inline message edit initializer should remain inspectable");
        assert!(!begin.contains("open_dialog"));
        assert!(begin.contains("input.set_value(initial"));
        assert!(begin.contains("input.focus(window, cx)"));
        assert!(begin.contains("remove(&measured_turn_id)"));
        assert!(begin.contains("self.session_turn_pending(&source_session_id)"));

        let replacement = source
            .split_once("    fn replace_latest_user_message(")
            .and_then(|(_, tail)| tail.split_once("\n    fn open_new_session("))
            .map(|(body, _)| body)
            .expect("inline message replacement should remain inspectable");
        assert!(replacement.contains(".replace_user_message("));
        assert!(!replacement.contains(".fork_session("));
        assert!(!replacement.contains("archive_session_if_timeline_unchanged"));
        assert!(!replacement.contains("self.agent_action_pending = true"));
        assert!(replacement.contains("this.refresh_selected_agent_timeline(cx)"));

        let renderer = source
            .split_once("    fn render_user_message_row(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_agent_message_row("))
            .map(|(body, _)| body)
            .expect("user message renderer should remain inspectable");
        assert!(renderer.contains("render_inline_user_message_editor"));
        assert!(source.contains("MarkdownView::plain_text(id"));
        let timestamp_index = renderer
            .find(".when_some(timestamp")
            .expect("timestamp should be rendered for the user message actions");
        let copy_index = renderer
            .find("Button::new(format!(\"copy-user-message:")
            .expect("copy action should remain available");
        let edit_index = renderer
            .find("Button::new(format!(\"edit-user-message:")
            .expect("edit action should remain available");
        assert!(timestamp_index < copy_index && copy_index < edit_index);
        assert!(!renderer.contains(".label(locale::text(\"Copy\""));
        assert!(!renderer.contains(".label(locale::text(\"Edit\""));
        assert!(renderer.contains(".tooltip(locale::text(\"Copy\""));
        assert!(renderer.contains(".tooltip(locale::text(\"Edit\""));
        let editor = source
            .split_once("    fn render_inline_user_message_editor(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_user_message_row("))
            .map(|(body, _)| body)
            .expect("inline user message editor should remain inspectable");
        assert!(editor.contains("Input::new(&self.user_message_edit_input)"));
        assert!(editor.contains("cancel-inline-message-edit"));
        assert!(editor.contains("submit-inline-message-edit"));
        assert!(!editor.contains(".border_1()"));
        assert!(!editor.contains(".border_color("));
        let legacy_prompt = ["prompt_edit_latest", "_user_message"].concat();
        assert!(!source.contains(&legacy_prompt));
    }

    #[test]
    fn pending_user_message_edit_replaces_the_user_row_and_hides_the_old_response() {
        let session_id = VibexSessionId::parse("session_pending_edit").unwrap();
        let timeline_item =
            |sequence: i64, timestamp_ms: i64, source: TimelineSource, payload: TimelinePayload| {
                let kind = payload.kind();
                TimelineItem {
                    id: TimelineItemId::new(),
                    session_id: session_id.clone(),
                    sequence,
                    timestamp_ms,
                    source,
                    kind,
                    correlation_id: None,
                    provider_correlation_id: None,
                    redaction_state: TimelineRedactionState::None,
                    execution_attribution: None,
                    payload,
                }
            };
        let mut timeline = TimelineModel::default();
        timeline.replace_authoritative(
            session_id.clone(),
            [
                timeline_item(
                    7,
                    10,
                    TimelineSource::User,
                    TimelinePayload::UserMessage(UserMessagePayload {
                        text: "old prompt".into(),
                        attachments: Vec::new(),
                    }),
                ),
                timeline_item(
                    8,
                    11,
                    TimelineSource::Agent,
                    TimelinePayload::AgentMessage(AgentMessagePayload {
                        text: "old response".into(),
                        is_final: true,
                    }),
                ),
            ],
        );
        let attachment = MessageAttachment {
            label: "notes.txt".into(),
            mime_type: Some("text/plain".into()),
            uri: None,
            inline_text_offset: None,
        };
        let pending = PendingUserMessageEdit {
            source_session_id: session_id,
            user_sequence: 7,
            submitted_at_ms: 20,
            text: "edited prompt".into(),
            attachments: vec![attachment.clone()],
        };

        let projected = pending.projected_items(&timeline).unwrap();

        assert_eq!(projected.len(), 1);
        assert_eq!(
            timeline.items.len(),
            2,
            "authoritative timeline stays intact"
        );
        assert_eq!(projected[0].timestamp_ms, 20);
        let TimelinePayload::UserMessage(message) = &projected[0].payload else {
            panic!("projected item should remain a user message");
        };
        assert_eq!(message.text, "edited prompt");
        assert_eq!(message.attachments, vec![attachment]);
        let turns = timeline_conversation_turns(&projected, Some(AgentSessionState::Running), true);
        assert_eq!(turns.len(), 1);
        assert!(!turns[0].complete);
        assert!(turns[0].conclusion_row.is_none());
    }

    #[test]
    fn optimistic_user_message_projects_until_matching_authoritative_row_arrives() {
        let session_id = VibexSessionId::parse("session_optimistic_message").unwrap();
        let attachment = MessageAttachment {
            label: "notes.txt".into(),
            mime_type: Some("text/plain".into()),
            uri: None,
            inline_text_offset: None,
        };
        let optimistic = OptimisticUserMessage {
            session_id: session_id.clone(),
            item_id: TimelineItemId::new(),
            after_sequence: 1,
            submitted_at_ms: 20,
            text: "  first prompt  ".into(),
            attachments: vec![attachment.clone()],
        };
        let timeline = TimelineModel::default();
        let projected = optimistic.projected_items(&timeline).unwrap();
        assert_eq!(projected.len(), 1);
        assert_eq!(timeline.items.len(), 0);
        assert_eq!(projected[0].sequence, 1);
        let pending_turns =
            timeline_conversation_turns(&projected, Some(AgentSessionState::Running), true);
        assert_eq!(pending_turns.len(), 1);
        assert_eq!(
            pending_turns[0]
                .user_row
                .as_ref()
                .map(|row| row.body.trim()),
            Some("first prompt")
        );
        assert!(!pending_turns[0].complete);
        assert!(pending_turns[0].conclusion_row.is_none());

        let failed_turns =
            timeline_conversation_turns(&projected, Some(AgentSessionState::Error), false);
        assert_eq!(failed_turns.len(), 1);
        assert_eq!(
            failed_turns[0].user_row.as_ref().map(|row| row.body.trim()),
            Some("first prompt"),
            "a terminal send failure must keep the captured user message visible"
        );

        let mut timeline = TimelineModel::default();
        timeline.replace_authoritative(
            session_id.clone(),
            [timeline_item_with_payload(
                &session_id,
                2,
                TimelineSource::User,
                TimelinePayload::UserMessage(UserMessagePayload {
                    text: "first prompt".into(),
                    attachments: vec![attachment.clone()],
                }),
            )],
        );
        assert!(optimistic.projected_items(&timeline).is_none());
        let authoritative_turns = timeline.conversation_turns(Some(AgentSessionState::Idle), false);
        assert_eq!(authoritative_turns.len(), 1);
        assert_eq!(
            authoritative_turns[0]
                .user_row
                .as_ref()
                .map(|row| row.body.as_str()),
            Some("first prompt")
        );
    }

